USE vmmon;
ALTER TABLE users ADD COLUMN last_login DATETIME NULL, ADD COLUMN last_seen DATETIME NULL, ADD COLUMN logged_in TINYINT NOT NULL DEFAULT 0;
CREATE TABLE check_events(id BIGINT AUTO_INCREMENT PRIMARY KEY, ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP, check_id INT NULL, server_name VARCHAR(80), svc TINYINT NOT NULL DEFAULT 0, label VARCHAR(120), target VARCHAR(255), status ENUM('up','down') NOT NULL, detail VARCHAR(255), dur INT NULL, INDEX(check_id,id), INDEX(ts));
